        F("Тейлор коэффициенттері", r"c_n=\frac{f^{(n)}(a)}{n!}=\frac1{2\pi i}\oint\frac{f(w)}{(w-a)^{n+1}}dw", r"Радиус - ең жақын ерекше нүктеге дейінгі қашықтық.", r""),
        F("Лоран қатары", r"f(z)=\sum_{n=-\infty}^{\infty}c_n(z-a)^n,\qquad c_n=\frac1{2\pi i}\oint\frac{f(w)}{(w-a)^{n+1}}dw", r"$\rho&lt;|z-a|&lt;R$ сақинасында.", r""),
        F("Геометриялық жіктелу", r"\frac1{1-q}=\sum_{n=0}^\infty q^n\ (|q|&lt;1),\qquad\frac{1}{z-b}=-\sum_{n=0}^{\infty}\frac{z^n}{b^{n+1}}\ (|z|&lt;|b|)", r"Лоран жіктеуінің негізгі құралы.", r""),
        F("Сыртқы сақинада", r"\frac1{z-b}=\sum_{n=0}^{\infty}\frac{b^n}{z^{n+1}}\quad(|z|&gt;|b|)", r"$\frac1z\cdot\frac1{1-b/z}$.", r""),
        F("Полюс реті", r"f(z)=\frac{g(z)}{(z-a)^m},\qquad g(a)\ne0", r"$a$ - $m$-ретті полюс; бөлшекте реті = бөлгіш нөлінің реті минус алым нөлінің реті (оң болса).", r""),
